(3045745, 429208, 16241, '<td valign="top">nice one.</td>', 'nice one.', '2006-11-20 01:50:16.000000', NULL, 1),
(3045752, 427210, 66515, '<td valign="top">Great shot. This challenge allowed you to add text. Doing this would have given this more of a postcard feel to it. 7</td>', 'Great shot. This challenge allowed you to add text. Doing this would have given this more of a postcard feel to it. 7', '2006-11-20 01:52:13.000000', NULL, 1),
(3045754, 428135, 66515, '<td valign="top">Great shot but its a lttile dark.</td>', 'Great shot but its a lttile dark.', '2006-11-20 01:52:47.000000', NULL, 1),
(3045758, 429190, 66515, '<td valign="top">The bottom area should be smaller as the text is distracting. (I would say it should be about the same size as the bottom line of text).</td>', 'The bottom area should be smaller as the text is distracting. (I would say it should be about the same size as the bottom line of text).', '2006-11-20 01:53:48.000000', NULL, 1),
(3045759, 429260, 66515, '<td valign="top">Very static image that is to be honest kinda boring. There is nothing here that is especially interesting to look at.</td>', 'Very static image that is to be honest kinda boring. There is nothing here that is especially interesting to look at.', '2006-11-20 01:55:18.000000', NULL, 1),
(3045761, 429439, 66515, '<td valign="top">I really like this shot however you took away a lot by using the black area to put the text in (about a full third of the frame actually). A different color of font etc and placed elsewhere would allow you to show more of the bridge.</td>', 'I really like this shot however you took away a lot by using the black area to put the text in (about a full third of the frame actually). A different color of font etc and placed elsewhere would allow you to show more of the bridge.', '2006-11-20 01:56:45.000000', NULL, 1),
(3045763, 428775, 66515, '<td valign="top">This could do with a bit of saturation and better contrast. You have a great composition here but the colors are a bit dull.</td>', 'This could do with a bit of saturation and better contrast. You have a great composition here but the colors are a bit dull.', '2006-11-20 01:57:41.000000', NULL, 1),
(3045768, 429046, 66515, '<td valign="top">A bit oversaturated for my tastes. The inn has a strange "glow" because of it.</td>', 'A bit oversaturated for my tastes. The inn has a strange "glow" because of it.', '2006-11-20 02:00:32.000000', NULL, 1),
(3045774, 429283, 66515, '<td valign="top">I think a shot of the Manor itself would be more interesting than a picture of a chair. just my opinion of course...</td>', 'I think a shot of the Manor itself would be more interesting than a picture of a chair. just my opinion of course...', '2006-11-20 02:02:36.000000', NULL, 1),
(3045775, 428692, 66515, '<td valign="top">The silhouette effect is nice but I would like to see more detail in the statue in the foreground. 6</td>', 'The silhouette effect is nice but I would like to see more detail in the statue in the foreground. 6', '2006-11-20 02:03:29.000000', NULL, 1),
(3045777, 429229, 42013, '<td valign="top">eclectic in a good way!</td>', 'eclectic in a good way!', '2006-11-20 02:05:22.000000', NULL, 1),
(3045779, 428415, 66515, '<td valign="top">Not really a great postcard shot. DNMC</td>', 'Not really a great postcard shot. DNMC', '2006-11-20 02:05:43.000000', NULL, 1),
(3045781, 429184, 66515, '<td valign="top">Interesting shot and well captured...however I think the reflection of your vehicle takes away from it.</td>', 'Interesting shot and well captured...however I think the reflection of your vehicle takes away from it.', '2006-11-20 02:06:18.000000', NULL, 1),
(3045786, 429349, 66515, '<td valign="top">Unfortunately it appears you were a little heavy handed with the saturation. The sky looks quite artificial and detracts from the quality of this shot.</td>', 'Unfortunately it appears you were a little heavy handed with the saturation. The sky looks quite artificial and detracts from the quality of this shot.', '2006-11-20 02:07:36.000000', NULL, 1),
(3045787, 428358, 33352, '<td valign="top">Great postcard and contrasting colors,christmas decorations fit the time of year well..Good Luck...</td>', 'Great postcard and contrasting colors,christmas decorations fit the time of year well..Good Luck...', '2006-11-20 02:07:48.000000', NULL, 1),
(3045790, 429326, 42013, '<td valign="top">Great shot. Powerful leading lines and the bridge structure is so unique.</td>', 'Great shot. Powerful leading lines and the bridge structure is so unique.', '2006-11-20 02:08:52.000000', NULL, 1),
