(3047290, 429396, 41536, '<td valign="top">Perspective is very good.</td>', 'Perspective is very good.', '2006-11-20 11:15:39.000000', NULL, 1),
(3047294, 429294, 64929, '<td valign="top">Wow, what a capture!  Would have been better with text</td>', 'Wow, what a capture!  Would have been better with text', '2006-11-20 11:17:05.000000', NULL, 1),
