(3048556, 428149, 66597, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2006-11-20 17:31:59.000000', NULL, 1),
(3048558, 429364, 66597, '<td valign="top">What stunning lighting. Great shot.</td>', 'What stunning lighting. Great shot.', '2006-11-20 17:32:37.000000', NULL, 1),
(3048563, 429202, 66597, '<td valign="top">There''s an odd reflection in the sky and the castle is not in focus. The font is nice.</td>', 'There''s an odd reflection in the sky and the castle is not in focus. The font is nice.', '2006-11-20 17:34:16.000000', NULL, 1),
(3048564, 429434, 46031, '<td valign="top">the image looks awesome. i like the telephoto effect that brings the buildings closer together. the colors look really great. the text looks a little weird and to me doesn''t seem to fit the general look of the image/postcard.</td>', 'the image looks awesome. i like the telephoto effect that brings the buildings closer together. the colors look really great. the text looks a little weird and to me doesn''t seem to fit the general look of the image/postcard.', '2006-11-20 17:34:22.000000', NULL, 1),
(3048566, 428811, 66597, '<td valign="top">LOL.</td>', 'LOL.', '2006-11-20 17:34:46.000000', NULL, 1),
(3048569, 428397, 66597, '<td valign="top">I think this is a very good photo - but not a great postcard. There is something vaguely sinister about it.</td>', 'I think this is a very good photo - but not a great postcard. There is something vaguely sinister about it.', '2006-11-20 17:35:52.000000', NULL, 1),
(3048571, 429063, 66597, '<td valign="top">Land looks a bit overexposed to me.</td>', 'Land looks a bit overexposed to me.', '2006-11-20 17:36:39.000000', NULL, 1),
